window.particlesJS = function(divId, config) {
    var container = document.getElementById(divId);
    if(!container) return;

    var oldCanvas = container.querySelector('canvas');
    if (oldCanvas) {
        container.removeChild(oldCanvas);
    }

    var canvas = document.createElement('canvas');
    canvas.style.position = 'absolute';
    canvas.style.width = "100%"; 
    canvas.style.height = "100%";
    container.appendChild(canvas);
    var ctx = canvas.getContext('2d');
    
    var dots = [];
    var width = 0;
    var height = 0;

    // Функция для перевода HEX цвета в RGB (нужна для прозрачности)
    function hexToRgb(hex) {
        var result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        return result ? {
            r: parseInt(result[1], 16),
            g: parseInt(result[2], 16),
            b: parseInt(result[3], 16)
        } : { r: 0, g: 255, b: 204 };
    }

    // Берем цвет из CSS-переменной --primary
    var primaryColor = getComputedStyle(document.body).getPropertyValue('--primary').trim();
    // Если не удалось получить, используем цвет из конфига
    if (!primaryColor) primaryColor = config.particles.color.value;
    var rgb = hexToRgb(primaryColor);

    function resize() {
        width = container.offsetWidth;
        height = container.offsetHeight;
        canvas.width = width;
        canvas.height = height;
    }
    
    window.addEventListener('resize', function() {
        resize();
        dots.forEach(function(d) {
            if(d.x > width) d.x = Math.random() * width;
            if(d.y > height) d.y = Math.random() * height;
        });
    });
    
    resize();

    // Создаем частицы
    for(var i=0; i<config.particles.number.value; i++) {
        dots.push({
            x: Math.random() * width,
            y: Math.random() * height, 
            size: Math.random() * config.particles.size.value + 0.5,
            speed: Math.random() * config.particles.move.speed + 0.2,
            alpha: Math.random() * 0.6 + 0.1
        });
    }
    
    function draw() {
        ctx.clearRect(0, 0, width, height);
        
        dots.forEach(function(d) {
            d.y -= d.speed;
            
            if(d.y < -d.size * 2) {
                d.y = height + d.size * 2;
                d.x = Math.random() * width;
                d.alpha = Math.random() * 0.6 + 0.1; 
            }
            
            d.x += Math.sin(d.y * 0.01) * 0.2;

            ctx.shadowBlur = 8;
            ctx.shadowColor = primaryColor;
            
            // ИСПОЛЬЗУЕМ ДИНАМИЧЕСКИЙ ЦВЕТ ИЗ КОНФИГА
            ctx.fillStyle = "rgba(" + rgb.r + ", " + rgb.g + ", " + rgb.b + ", " + d.alpha + ")";
            ctx.beginPath();
            ctx.arc(d.x, d.y, d.size, 0, Math.PI * 2);
            ctx.fill();
        });
        
        ctx.shadowBlur = 0;
        requestAnimationFrame(draw);
    }
    draw();
};